/* ------------------------------------------------------------------ /proc/self/maps and cmdline */
static char maps[MAPS_CAP];
static u64 maps_len;
static char cmdline[2048];
static u64 read_all(const char *path, char *dst, u64 cap)
{
    i64 fd = sys_open(path, F_RDONLY, 0);
    u64 got = 0;
    if (fd < 0) return 0;
    for (;;) {
        i64 r = sys_read((int)fd, dst + got, cap - 1 - got);
        if (r <= 0) break;
        got += (u64)r;
        if (got >= cap - 1) break;
    }
    sys_close((int)fd);
    dst[got] = 0;
    return got;
}
static u64 hexval(const char **p)
{
    u64 v = 0;
    for (;; (*p)++) {
        char c = **p; int d;
        if (c >= '0' && c <= '9') d = c - '0'; else if (c >= 'a' && c <= 'f') d = c - 'a' + 10; else break;
        v = v << 4 | (u64)d;
    }
    return v;
}
static int ends_with(const char *s, u64 n, const char *suffix)
{
    u64 m = slen(suffix);
    if (n < m) return 0;
    return same((const u8 *)s + n - m, (const u8 *)suffix, m);
}
static u64 mapped_at(const char *name, u64 off, char *path, u64 pathcap)
{
    const char *p = maps, *end = maps + maps_len;
    u64 found = 0;
    while (p < end) {
        const char *line = p, *q = p;
        while (p < end && *p != '\n') p++;
        u64 n = (u64)(p - line);
        if (p < end) p++;
        if (!ends_with(line, n, name)) continue;
        u64 lo = hexval(&q); if (*q != '-') continue; q++;
        u64 hi = hexval(&q); if (*q != ' ') continue; q++;
        char r = q[0];
        q += 5;
        u64 fo = hexval(&q);
        if (path && !path[0]) {
            const char *s = line + n;
            while (s > line && s[-1] != ' ') s--;
            u64 k = 0;
            for (; s < line + n && k + 1 < pathcap; s++) path[k++] = *s;
            path[k] = 0;
        }
        if (!found && r == 'r' && off >= fo && off < fo + (hi - lo)) found = lo + (off - fo);
    }
    return found;
}
static int cmdline_has(const char *needle)
{
    u64 m = slen(needle);
    for (u64 i = 0; cmdline[i]; i++) if (same((const u8 *)cmdline + i, (const u8 *)needle, m)) return 1;
    return 0;
}

/* ------------------------------------------------------------------ B: identity of the files */
static struct preflight_counts counts;
static void file_identity(void)
{
    puts_("== identity: files of this process\n");
    for (u64 i = 0; i < sizeof id_files / sizeof id_files[0]; i++) {
        char path[200]; path[0] = 0;
        u64 at = mapped_at(id_files[i].name, 0, path, sizeof path);
        puts_("file "); puts_(id_files[i].name);
        if (!path[0]) { puts_("  NOT MAPPED in this process\n"); counts.other++; continue; }
        puts_(" path "); puts_(path); puts_(" mapped "); putaddr(at); puts_("\n");
        i64 fd = sys_open(path, F_RDONLY, 0);
        if (fd < 0) { puts_("!! open failed "); putnum(fd); puts_("\n"); counts.other++; continue; }
        struct sha s; u8 dg[32]; u64 total = 0;
        sha_init(&s);
        for (;;) { i64 r = sys_read((int)fd, iobuf, sizeof iobuf); if (r <= 0) break; sha_add(&s, iobuf, (u64)r); total += (u64)r; }
        sys_close((int)fd);
        sha_end(&s, dg);
        int ok = same(dg, id_files[i].sha256, 32);
        puts_("  bytes "); putnum((i64)total); puts_(" sha256 "); puthex(dg, 32); puts_(ok ? "  SAME as the 2.02 update\n" : "  DIFFERS from the 2.02 update\n");
        if (!ok) counts.other++;
    }
}

/* ------------------------------------------------------------------ coprocessor reads */
extern u64 cam_dmm_alloc(u32 size, u32 *handle) __asm__("_Z9dmm_allocjPj");
extern u64 cam_dmm_free(u32 handle) __asm__("_Z8dmm_freej");
extern u32 sen_dma_transfer(u32 dir, u64 src, u64 dst, u32 size);

static const u8 *cp_buf;
static u64 cp_phys;
static int cp_ok;
static int cp_page(u32 page)
{
    if (!cp_ok) return 0;
    if (page & 0xfff || page < CP_LO || page >= CP_HI) { puts_("!! address outside the allowed range\n"); return 0; }
    u32 r = sen_dma_transfer(0, page, cp_phys, CP_PAGE);
    if (r) { puts_("!! transfer failed "); putnum(r); puts_(" at "); putaddr(page); puts_("; no further coprocessor reads\n"); cp_ok = 0; return 0; }
    return 1;
}
static int cp_bytes(u32 addr, u8 *dst, u32 len)
{
    while (len) {
        u32 page = addr & ~0xfffU, o = addr & 0xfff, n = CP_PAGE - o;
        if (n > len) n = len;
        if (!cp_page(page)) return 0;
        for (u32 i = 0; i < n; i++) dst[i] = cp_buf[o + i];
        addr += n; dst += n; len -= n;
    }
    return 1;
}
static u8 big[3072];
static void cp_part(void)
{
    u32 handle = 0;
    puts_("== coprocessor memory, read-only\n");
    cp_phys = cam_dmm_alloc(CP_PAGE, &handle);
    if (!cp_phys) { puts_("!! buffer allocation failed; no coprocessor reads\n"); counts.other++; return; }
    puts_("buffer physical "); putaddr(cp_phys); puts_(" handle "); putnum(handle); puts_("\n");
    if ((cp_phys & 0x3f) || cp_phys < RAM_LO || cp_phys + CP_PAGE > RAM_HI) { puts_("!! buffer address not usable; no coprocessor reads\n"); cam_dmm_free(handle); counts.other++; return; }
    i64 fd = sys_open("/dev/mem", F_RDONLY_SYNC, 0);
    if (fd < 0) { puts_("!! /dev/mem open failed "); putnum(fd); puts_("\n"); cam_dmm_free(handle); counts.other++; return; }
    u64 lead = cp_phys & 0xfff, maplen = (lead + CP_PAGE + 0xfff) & ~0xfffUL;
    i64 m = sys_mmap_ro((int)fd, maplen, cp_phys - lead);
    if (m == -1) { puts_("!! mmap of the buffer failed\n"); sys_close((int)fd); cam_dmm_free(handle); counts.other++; return; }
    cp_buf = (const u8 *)m + lead;
    cp_ok = 1;

    puts_("== identity: coprocessor code pages\n");
    for (u64 i = 0; i < sizeof id_pages / sizeof id_pages[0] && cp_ok; i++) {
        puts_("page "); putaddr(id_pages[i].address);
        if (!cp_page(id_pages[i].address)) { counts.other++; break; }
        struct sha s; u8 dg[32];
        sha_init(&s); sha_add(&s, cp_buf, CP_PAGE); sha_end(&s, dg);
        int ok = same(dg, id_pages[i].sha256, 32);
        puts_(" sha256 "); puthex(dg, 32); puts_(ok ? "  SAME as the 2.02 update\n" : "  DIFFERS from the 2.02 update\n");
        if (!ok) counts.other++;
    }

    puts_("== coprocessor sites\n");
    for (u64 i = 0; i < sizeof cp_sites / sizeof cp_sites[0] && cp_ok; i++) {
        const struct cp_site *c = &cp_sites[i];
        puts_("site "); puts_(c->name); puts_(" "); putaddr(c->address); puts_(" len "); putnum(c->length);
        if (c->length > sizeof big || !cp_bytes(c->address, big, c->length)) { puts_("  NOT READ\n"); counts.other++; continue; }
        int st = same(big, c->stock, c->length), tg = c->target && same(big, c->target, c->length);
        if (c->length <= 16) { puts_(" bytes "); puthex(big, c->length); }
        else {
            u32 d = 0;
            for (u32 k = 0; k < c->length; k++) if (big[k] != c->stock[k]) d++;
            puts_(" bytes differing from stock "); putnum(d);
        }
        puts_(st ? "  STOCK\n" : tg ? "  TARGET\n" : c->soft ? "  OTHER (not counted: filled at run time)\n" : "  OTHER\n");
        observe_cp_site(&counts, c->name, c->soft, c->target != 0, st, tg);
        if (!st && !tg && c->length > 16) { puts_("other "); puts_(c->name); puts_(" "); puthex(big, c->length); puts_("\n"); }
    }
#if DUMP
    puts_("== coprocessor pages\n");
    for (u64 i = 0; i < sizeof dump_ranges / sizeof dump_ranges[0] && cp_ok; i++)
        for (u32 p = 0; p < dump_ranges[i].pages && cp_ok; p++) {
            u32 a = dump_ranges[i].address + p * CP_PAGE;
            if (!cp_page(a)) break;
            puts_("cppage "); puts_(dump_ranges[i].name); puts_(" "); putaddr(a); puts_(" "); puthex(cp_buf, CP_PAGE); puts_("\n");
        }
#endif
    sys_munmap((void *)m, maplen);
    sys_close((int)fd);
    cam_dmm_free(handle);
}

/* ------------------------------------------------------------------ D: main-processor sites */
static int is_mp4_hdr_off(u64 off)
{
    return off == 0x20794cUL || off == 0x207aa8UL ||
           off == 0x207d8cUL || off == 0x207dd8UL || off == 0x20a194UL ||
           off == 0x20a198UL || off == 0x238108UL || off == 0x238114UL;
}

static void mp_report(const struct mp_site *e, const u8 *v, int is_lm)
{
    int st = same(v, e->stock, e->length), tg = same(v, e->target, e->length);
    int is_header = is_lm && is_mp4_hdr_off(e->offset);
    puts_(" bytes "); puthex(v, e->length); puts_(st ? "  STOCK\n" : tg ? "  TARGET\n" : "  OTHER\n");
    observe_mp_site(&counts, is_header, st, tg);
}
static void mp_part(void)
{
    puts_("== main-processor sites: libmpr.so in this process\n");
    for (u64 i = 0; i < sizeof lm_sites / sizeof lm_sites[0]; i++) {
        const struct mp_site *e = &lm_sites[i];
        u64 at = mapped_at("/libmpr.so", e->offset, 0, 0);
        puts_("lm "); putaddr(e->offset);
        if (!at || !mapped_at("/libmpr.so", e->offset + e->length - 1, 0, 0)) { puts_("  NOT MAPPED\n"); counts.other++; continue; }
        puts_(" at "); putaddr(at);
        mp_report(e, (const u8 *)at, 1);
    }
    puts_("== main-processor sites: av-cam.bin in kernel memory\n");
    if (!cmdline_has(AVCAM_RESERVE)) {
        puts_("!! the kernel command line does not reserve memory as " AVCAM_RESERVE "; av-cam.bin is not read\n");
        counts.other++;
        return;
    }
    i64 fd = sys_open("/dev/mem", F_RDONLY, 0);
    if (fd < 0) { puts_("!! /dev/mem open failed "); putnum(fd); puts_("\n"); counts.other++; return; }
    u64 lo = AV_LO & ~0xfffUL, len = ((AV_HI + 0xfff) & ~0xfffUL) - lo;
    i64 m = sys_mmap_ro((int)fd, len, AVCAM_PHYS + lo);
    if (m == -1) { puts_("!! mmap of av-cam.bin's tables failed\n"); sys_close((int)fd); counts.other++; return; }
    const u8 *av = (const u8 *)m - lo;
    for (u64 i = 0; i < sizeof av_guards / sizeof av_guards[0]; i++) {
        const struct av_guard *g = &av_guards[i];
        struct sha s; u8 dg[32];
        sha_init(&s); sha_add(&s, av + g->offset, g->length); sha_end(&s, dg);
        int ok = same(dg, g->sha256, 32);
        puts_("guard "); puts_(g->name); puts_(" "); putaddr(g->offset); puts_(" len "); putnum(g->length); puts_(ok ? "  SAME\n" : "  DIFFERS\n");
        if (!ok) counts.other++;
    }
    for (u64 i = 0; i < sizeof av_sites / sizeof av_sites[0]; i++) {
        puts_("av "); putaddr(av_sites[i].offset);
        mp_report(&av_sites[i], av + av_sites[i].offset, 0);
    }
    sys_munmap((void *)m, len);
    sys_close((int)fd);
}

/* ------------------------------------------------------------------ run */
static void run(void)
{
    i64 fd = sys_open(RESULT_PATH, F_NEW, 0600);
    if (fd < 0) return;
    out_fd = (int)fd;
    puts_("zvread " ZV_LABEL); puts_(DUMP ? " dump" : " check"); puts_(" for ZV-E1 2.02; read-only\n");
    static const char *const files[] = { "/proc/version", "/proc/cmdline", "/proc/iomem", "/proc/mounts", "/proc/modules", "/proc/meminfo", "/proc/self/status" };
    for (u64 i = 0; i < sizeof files / sizeof files[0]; i++) copy_file(files[i], FILE_CAP);
    maps_len = read_all("/proc/self/maps", maps, sizeof maps);
    read_all("/proc/cmdline", cmdline, sizeof cmdline);
    puts_("== file /proc/self/maps\n"); put(maps, maps_len); puts_("\n== end "); putnum((i64)maps_len); puts_(" bytes\n");
#if DUMP
    copy_dir("/sys/module/liro/parameters", 256);
    copy_dir("/log", 2048);
#endif
    file_identity();
    cp_part();
    mp_part();
    unsigned int target_total = counts.cp_og_target + counts.sr_target + counts.oz_target +
        counts.sc0_target + counts.scf_target + counts.mp_base_target + counts.mp_hdr_target;
    puts_("== summary\nplaces not as the 2.02 update or not read: "); putnum(counts.other);
    puts_("\nnon-stock target values: "); putnum(target_total);
    puts_(preflight_verdict(&counts));
    puts_("== done\n");
    sys_close((int)fd);
    out_fd = -1;
}

__attribute__((constructor)) static void zvread_ctor(void) { run(); }
